        let y = vec![4.0, 5.0];
        let (xg, yg) = meshgrid(x, y);

        // xg should be 2 rows, each [1.0, 2.0, 3.0]
        assert_eq!(xg.len(), 2);
        assert_eq!(xg[0], vec![1.0, 2.0, 3.0]);
        assert_eq!(xg[1], vec![1.0, 2.0, 3.0]);

